from __future__ import annotations

from datetime import UTC, datetime, timedelta

from catalyst_router.domain import (
    AgentMode,
    DecisionRecord,
    OrderExecutionStatus,
    ReconciliationSnapshot,
)
from catalyst_router.ports import OperationalStore, PaperBroker


class ReconciliationService:
    def __init__(self, *, broker: PaperBroker, store: OperationalStore) -> None:
        self._broker = broker
        self._store = store

    def reconcile(self) -> ReconciliationSnapshot:
        state = self._store.begin_execution()
        snapshot = self._broker.reconciliation_snapshot()
        self.validate_snapshot(snapshot)
        self._reconcile_active_order(snapshot)
        record = DecisionRecord.create(
            decision_type="RECONCILIATION_COMPLETED",
            summary=(
                f"Reconciled {len(snapshot.positions)} positions and "
                f"{len(snapshot.open_orders)} open orders"
            ),
            payload={
                "market_is_open": snapshot.clock.is_open,
                "position_count": len(snapshot.positions),
                "open_order_count": len(snapshot.open_orders),
                "options_trading_level": snapshot.account.options_trading_level,
            },
            public=True,
            public_summary=(
                f"Reconciled {len(snapshot.positions)} positions and "
                f"{len(snapshot.open_orders)} open orders"
            ),
        )
        self._store.commit_reconciliation(
            state.execution_epoch, record, equity=snapshot.account.equity
        )
        return snapshot

    def _reconcile_active_order(self, snapshot: ReconciliationSnapshot) -> None:
        state = self._store.get_agent_state()
        client_order_id = state.active_order_id
        if client_order_id is None:
            return
        execution = self._store.get_order(client_order_id)
        if execution is None:
            raise RuntimeError("active order has no durable execution record")
        broker_order = self._broker.get_order_by_client_id(client_order_id)
        if broker_order is None:
            if (
                not snapshot.positions
                and not snapshot.open_orders
                and snapshot.clock.timestamp >= execution.plan.expires_at
            ):
                self._store.clear_active_order(client_order_id)
                return
            if state.mode is AgentMode.RUNNING and execution.status in {
                OrderExecutionStatus.PREPARED,
                OrderExecutionStatus.UNKNOWN,
            }:
                self._store.transition_agent_mode(
                    AgentMode.RISK_HALTED,
                    reason="ambiguous order was not found during reconciliation",
                    record=DecisionRecord.create(
                        decision_type="ORDER_RECONCILIATION_HALTED",
                        summary=f"could not resolve {client_order_id}",
                    ),
                )
            return
        plan = execution.plan
        if (
            broker_order.symbol != plan.symbol
            or broker_order.side is not plan.side
            or broker_order.quantity != plan.quantity
        ):
            raise RuntimeError("broker order does not match its durable order plan")
        status = broker_order.status.rsplit(".", 1)[-1].lower()
        rejected = status in {"canceled", "expired", "rejected", "replaced"}
        target = OrderExecutionStatus.REJECTED if rejected else OrderExecutionStatus.ACKNOWLEDGED
        if execution.status is not target:
            previous_status = execution.status
            execution = execution.model_copy(
                update={
                    "status": target,
                    "version": execution.version + 1,
                    "alpaca_order_id": broker_order.order_id,
                    "broker_status": broker_order.status,
                    "updated_at": datetime.now(UTC),
                }
            )
            self._store.update_order(execution, expected_status=previous_status)
        if not snapshot.positions and not snapshot.open_orders and (rejected or status == "filled"):
            self._store.clear_active_order(client_order_id)

    @staticmethod
    def validate_snapshot(snapshot: ReconciliationSnapshot) -> None:
        now = datetime.now(UTC)
        if snapshot.account.trading_blocked:
            raise RuntimeError("Alpaca account is blocked from trading")
        if snapshot.account.equity <= 0 or snapshot.account.portfolio_value <= 0:
            raise RuntimeError("Alpaca account values are invalid")
        if not now - timedelta(seconds=30) <= snapshot.captured_at <= now + timedelta(seconds=5):
            raise RuntimeError("Alpaca reconciliation snapshot is stale")
        if len(snapshot.open_orders) >= 500:
            raise RuntimeError("open-order response may be truncated")

from __future__ import annotations

from dataclasses import dataclass

from catalyst_router.adapters.alpaca import AlpacaPaperBroker
from catalyst_router.adapters.dynamodb import DynamoOperationalStore
from catalyst_router.adapters.market_data import AlpacaIEXMarketData
from catalyst_router.adapters.memory import InMemoryOperationalStore
from catalyst_router.challenger import ShadowChallenger
from catalyst_router.execution import LiveTradingCycle, ModelStrategy
from catalyst_router.ports import OperationalStore, PaperBroker
from catalyst_router.service import ReconciliationService
from catalyst_router.settings import Settings
from catalyst_router.worker import TradingWorker


@dataclass(slots=True)
class Container:
    settings: Settings
    store: OperationalStore
    broker: PaperBroker | None
    challenger: ShadowChallenger | None = None
    market_data: AlpacaIEXMarketData | None = None

    @classmethod
    def build(cls, settings: Settings) -> Container:
        if settings.state_backend == "memory":
            store: OperationalStore = InMemoryOperationalStore(settings.public_delay_seconds)
        elif settings.state_backend == "dynamodb":
            store = DynamoOperationalStore(
                table_name=settings.dynamodb_table,
                competition_id=settings.competition_id,
                region=settings.aws_region,
                endpoint_url=settings.dynamodb_endpoint_url,
                public_delay_seconds=settings.public_delay_seconds,
                initialize_missing=settings.runtime_role != "reporting",
            )
        else:
            raise ValueError(f"unsupported STATE_BACKEND: {settings.state_backend}")
        if settings.runtime_role != "reporting":
            store.initialize()

        broker: PaperBroker | None = None
        market_data = None
        if settings.runtime_role != "reporting" and settings.alpaca_key and settings.alpaca_secret:
            broker = AlpacaPaperBroker(settings.alpaca_key, settings.alpaca_secret)
            market_data = AlpacaIEXMarketData(settings.alpaca_key, settings.alpaca_secret)
        if settings.auto_reconcile and broker is None:
            raise RuntimeError("AUTO_RECONCILE requires Alpaca credentials")
        challenger = None
        if settings.challenger_manifest_uri:
            if not settings.challenger_manifest_sha256:
                raise RuntimeError(
                    "CHALLENGER_MANIFEST_SHA256 is required with CHALLENGER_MANIFEST_URI"
                )
            challenger = ShadowChallenger.load_from_s3(
                settings.challenger_manifest_uri,
                settings.aws_region,
                settings.challenger_manifest_sha256,
            )
            if settings.model_authority == "PAPER_LIVE":
                challenger.authorize_paper_execution(settings.model_decision_gate)
        return cls(
            settings=settings,
            store=store,
            broker=broker,
            challenger=challenger,
            market_data=market_data,
        )

    def reconciliation_service(self) -> ReconciliationService:
        if self.broker is None:
            raise RuntimeError("Alpaca credentials are not configured")
        return ReconciliationService(broker=self.broker, store=self.store)

    def trading_worker(self) -> TradingWorker:
        if self.market_data is None:
            raise RuntimeError("Alpaca market data credentials are not configured")
        if self.challenger is None:
            raise RuntimeError("a challenger model is not configured")
        live_trader = None
        if self.settings.paper_execution_enabled:
            if self.broker is None:
                raise RuntimeError("paper execution requires Alpaca trading credentials")
            live_trader = LiveTradingCycle(
                store=self.store,
                broker=self.broker,
                quotes=self.market_data,
                strategy=(
                    ModelStrategy(
                        self.challenger,
                        decision_gate=self.settings.model_decision_gate,
                    )
                    if self.settings.model_execution_enabled
                    else None
                ),
            )
        return TradingWorker(
            store=self.store,
            market_data=self.market_data,
            challenger=self.challenger,
            live_trader=live_trader,
        )

